edits.old:
  while (!existsSync(head)) {
    const up = dirname(head);
    if (up === head) return path;
    tail.unshift(head.slice(up.length).replace(/^\//, ''));
    head = up;
  }
  return resolve(realpathSync(head), ...tail);
}

edits.new:
  for (;;) {
    if (existsSync(head)) {
      try {
        return resolve(realpathSync(head), ...tail);
      } catch {}
    }
    const up = dirname(head);
    if (up === head) return path;
    tail.unshift(head.slice(up.length).replace(/^\//, ''));
    head = up;
  }
}
